// 流内重试的三家一致性（2026-10-23）。
//
// 动因是一次**实测出来的不对称**：`streamOpenAI` 早在 2026-09-30 就有了「对端把 5xx 塞进 SSE 体
//（HTTP 200）」的流内重试，而 anthropic / gemini 两个适配器**一次就打死整轮任务**。
// 实测（同一条探针，只换适配器）：
//   OpenAI  首帧 server_error      ⇒ FETCH CALLS = 2，正常收尾
//   Anthropic 首帧 overloaded_error ⇒ FETCH CALLS = 1，抛错
//   Gemini  首帧 RESOURCE_EXHAUSTED ⇒ FETCH CALLS = 1，抛错
// 三家共用同一份判据（`retry.ts` 的 `retryableStreamErrorFrame` / `retryableStreamFailure` /
// `StreamFailure`），所以本组判据也按「三家同一组边界」写：每一条不变量在三个适配器上各钉一次。
// **只钉一家就是半个判据**（第 675 页那个教训的同一形状）。
import { describe, expect, it } from "vitest";
import { mergeAssistantDeltas, type AssistantDeltaEvent } from "../src/events";
import type { ModelOutput, ProviderMessage } from "../src/providers";
import { streamAnthropic } from "../src/providers/anthropic";
import { streamGemini } from "../src/providers/gemini";
import { streamOpenAI } from "../src/providers/openai";
import { retryableStreamErrorFrame, StreamFailure } from "../src/providers/retry";

const USER: ProviderMessage[] = [{ role: "user", content: "hi" }];
const enc = new TextEncoder();

/** 每次调用**新造**一个 Response：body 是一次性的（读过即 locked），
 *  重试路径上复用同一个实例会拿到 "body object should not be disturbed or locked"
 *  —— 那条错会盖住真正要验的重试语义。 */
const sse = (frames: readonly string[]): Response =>
  new Response(new ReadableStream<Uint8Array>({
    start(c) { for (const f of frames) c.enqueue(enc.encode(f + "\n")); c.close(); },
  }), { status: 200, headers: { "content-type": "text/event-stream" } });

async function collect(iter: AsyncIterable<ModelOutput>): Promise<ModelOutput[]> {
  const out: ModelOutput[] = [];
  for await (const e of iter) out.push(e);
  return out;
}
const textOf = (events: ModelOutput[]): string =>
  mergeAssistantDeltas(events.filter((e): e is AssistantDeltaEvent => e.type === "assistant_delta"));

// ---- 三家各自的「成功收尾」与「未吐输出的可重试错误」帧 ----
interface Arm {
  readonly name: string;
  /** 只含文本增量的一次正常收尾。 */
  readonly ok: readonly string[];
  /** 一个输出都没吐就报错、且**应当**重试的帧（HTTP 200 的 SSE 体内）。 */
  readonly retryable: readonly string[];
  /** 吐了半句正文。 */
  readonly partial: readonly string[];
  /** 一个输出都没吐就报错、且**不应**重试的帧（请求本身的问题）。 */
  readonly fatal: readonly string[];
  readonly stream: (fetchImpl: typeof fetch, signal?: AbortSignal) => AsyncIterable<ModelOutput>;
}

const ARMS: readonly Arm[] = [
  {
    name: "OpenAI 兼容",
    ok: ["data: " + JSON.stringify({ choices: [{ delta: { content: "ok" } }] }), "data: [DONE]"],
    retryable: ["data: " + JSON.stringify({ error: { type: "server_error", message: "boom" } })],
    partial: ["data: " + JSON.stringify({ choices: [{ delta: { content: "半" } }] })],
    fatal: ["data: " + JSON.stringify({ error: { type: "invalid_request_error", message: "bad" } })],
    stream: (f, signal) => streamOpenAI(USER, { apiKey: "t", baseURL: "https://x.test/v1", fetchImpl: f }, undefined, signal === undefined ? undefined : { signal }),
  },
  {
    name: "Anthropic",
    ok: [
      'event: content_block_delta',
      'data: {"type":"content_block_delta","index":0,"delta":{"type":"text_delta","text":"ok"}}',
    ],
    retryable: [
      'event: error',
      'data: {"type":"error","error":{"type":"overloaded_error","message":"Overloaded"}}',
    ],
    partial: [
      'event: content_block_delta',
      'data: {"type":"content_block_delta","index":0,"delta":{"type":"text_delta","text":"半"}}',
    ],
    fatal: [
      'event: error',
      'data: {"type":"error","error":{"type":"invalid_request_error","message":"bad"}}',
    ],
    stream: (f, signal) => streamAnthropic(USER, { apiKey: "t", fetchImpl: f }, undefined, signal === undefined ? undefined : { signal }),
  },
  {
    name: "Gemini",
    ok: ['data: {"candidates":[{"content":{"parts":[{"text":"ok"}]}}]}'],
    retryable: ['data: {"error":{"code":429,"message":"quota","status":"RESOURCE_EXHAUSTED"}}'],
    partial: ['data: {"candidates":[{"content":{"parts":[{"text":"半"}]}}]}'],
    fatal: ['data: {"error":{"code":400,"message":"bad","status":"INVALID_ARGUMENT"}}'],
    stream: (f, signal) => streamGemini(USER, { apiKey: "t", fetchImpl: f }, undefined, signal === undefined ? undefined : { signal }),
  },
];

describe.each(ARMS)("$name：流内失败的统一重试边界", (arm) => {
  it("首帧就是可重试错误（一个输出都没吐）⇒ 重试一次并把这一轮正常跑完", async () => {
    let calls = 0;
    const fetchImpl = (async () => {
      calls += 1;
      return calls === 1 ? sse(arm.retryable) : sse(arm.ok);
    }) as unknown as typeof fetch;
    const events = await collect(arm.stream(fetchImpl));
    expect(calls, "这一家没有重试 ⇒ 一次过载就打死了整轮任务").toBe(2);
    // 拿到的是**第二次**的内容，不是两次拼起来的两遍
    expect(textOf(events)).toBe("ok");
  });

  it("★ 反向哨兵：已经吐过正文之后再失败 ⇒ **不许重放**（重放会把同一轮吐两遍）", async () => {
    let calls = 0;
    const fetchImpl = (async () => {
      calls += 1;
      return sse([...arm.partial, ...arm.retryable]);
    }) as unknown as typeof fetch;
    await expect(collect(arm.stream(fetchImpl))).rejects.toThrow(/流错误/);
    expect(calls, "吐过输出还重放 = 模型看到重复内容，比失败更糟").toBe(1);
  });

  it("不可重放的错误不重试（请求本身的问题，重放只会再错一次并白烧预算）", async () => {
    let calls = 0;
    const fetchImpl = (async () => {
      calls += 1;
      return sse(arm.fatal);
    }) as unknown as typeof fetch;
    await expect(collect(arm.stream(fetchImpl))).rejects.toThrow(/流错误/);
    expect(calls).toBe(1);
  });

  it("重试次数有上限：连续失败不会无限打转", async () => {
    let calls = 0;
    const fetchImpl = (async () => {
      calls += 1;
      return sse(arm.retryable);
    }) as unknown as typeof fetch;
    await expect(collect(arm.stream(fetchImpl))).rejects.toThrow(/流错误/);
    expect(calls).toBeGreaterThan(1); // 确实重试过
    expect(calls).toBeLessThanOrEqual(3); // 但没有无限重试
  });

  it("退避期间调用方取消 ⇒ 立刻收束，不再打第二次", async () => {
    let calls = 0;
    const controller = new AbortController();
    const fetchImpl = (async () => {
      calls += 1;
      // 第一次就拿到可重试错误；随后在退避窗口里取消 ⇒ 重试必须被丢掉。
      queueMicrotask(() => controller.abort(new Error("用户停止")));
      return sse(arm.retryable);
    }) as unknown as typeof fetch;
    await expect(collect(arm.stream(fetchImpl, controller.signal))).rejects.toThrow();
    expect(calls, "取消之后还去打了第二次 = 把用户的停止当没看见").toBe(1);
  });
});

describe("三家共用同一份判据（`retry.ts`），不许各抄一份名字表", () => {
  it("数值优先：字符串形式的 502 也算可重试（OpenRouter 实测 `\"type\": \"502\"`）", () => {
    expect(retryableStreamErrorFrame({ names: ["502"] })).toBe(true);
    expect(retryableStreamErrorFrame({ names: [502] })).toBe(true);
    expect(retryableStreamErrorFrame({ names: [undefined, null] })).toBe(false);
  });

  it("名字表覆盖三家的过载/限流/可用性形状（大小写不敏感）", () => {
    for (const name of ["server_error", "overloaded_error", "api_error", "rate_limit_error", "timeout"]) {
      expect(retryableStreamErrorFrame({ names: [name] }), name).toBe(true);
    }
    for (const name of ["RESOURCE_EXHAUSTED", "UNAVAILABLE", "INTERNAL", "DEADLINE_EXCEEDED"]) {
      expect(retryableStreamErrorFrame({ names: [name] }), name).toBe(true);
    }
    // 网关可能把它们写成小写
    expect(retryableStreamErrorFrame({ names: ["resource_exhausted"] })).toBe(true);
  });

  it("请求本身的问题一律不可重放（400/401/403 家族与协议错）", () => {
    for (const name of ["invalid_request_error", "authentication_error", "permission_error", "INVALID_ARGUMENT"]) {
      expect(retryableStreamErrorFrame({ names: [name] }), name).toBe(false);
    }
    for (const code of [400, 401, 403, 404, 422, 451]) {
      expect(retryableStreamErrorFrame({ names: [code] }), String(code)).toBe(false);
    }
  });

  it("`StreamFailure` 的 retryable 是唯一出口：非 StreamFailure 的未知形状按可重放处理", () => {
    expect(new StreamFailure("boom", true).retryable).toBe(true);
    expect(new StreamFailure("boom", false).retryable).toBe(false);
  });
});

// 出网建连重试（能力 4「遇到失败能重试、换路径」+ 能力 9 运维面）。
// 此前三家 provider 的建连段是逐字同构的一段代码，且**零重试**：真实负载下首个 429/5xx
// 或一次网络抖动就把整轮任务打死（AGENTS.md 记过 provider:check 联网分支长期未证，正是这条路）。
import { DEFAULT_STALL_MS, stallGuard, type StallGuard } from "../net";

/** signal-aware sleep（2026-10-18）：本模块经 provider-draft → provider-config → registry 被
 *  renderer 引用（浏览器 bundle）。`node:timers/promises` 在浏览器侧被 externalize 成空模块，
 *  构建直接失败（"setTimeout is not exported by __vite-browser-external"）。语义与原实现一致：
 *  到点 resolve；中途 abort 则 clearTimeout 并 reject（上层 catch 仍以 callerSignal 原始原因优先）。 */
function delay(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    const abortError = (): Error => (signal?.reason instanceof Error ? signal.reason : new Error("Aborted"));
    if (signal?.aborted === true) { reject(abortError()); return; }
    const onAbort = (): void => { clearTimeout(timer); reject(abortError()); };
    const timer = setTimeout(() => { signal?.removeEventListener("abort", onAbort); resolve(); }, ms);
    signal?.addEventListener("abort", onAbort, { once: true });
  });
}
export { delay as waitRetryDelay };

/** 可重试的对端状态码：限流 / 服务器侧临时故障 / 请求超时。
 *  400/401/403/404/422 是**请求本身**的问题，重放只会再错一次并白烧预算 ⇒ 不在此列。 */
export function retryableStatus(status: number): boolean {
  return status === 408 || status === 409 || status === 425 || status === 429 || (status >= 500 && status <= 599);
}

/** Retry-After → 毫秒（支持「秒数」与 HTTP-date 两种形态）；不可解析返回 null。上限 capMs 钳住。 */
export function retryAfterMs(header: string | null | undefined, nowMs: number, capMs: number): number | null {
  if (header === null || header === undefined) return null;
  const trimmed = header.trim();
  if (trimmed === "") return null;
  const secs = Number(trimmed);
  if (Number.isFinite(secs)) return Math.min(Math.max(0, Math.round(secs * 1000)), capMs);
  const when = Date.parse(trimmed);
  if (!Number.isFinite(when)) return null;
  return Math.min(Math.max(0, Math.round(when - nowMs)), capMs);
}

/** 流内失败的分类：**重试与否由抛出处决定，不由 catch 处猜字符串**。
 *  判断「这个错能不能重放」需要的信息（5xx 还是协议错、帧坏还是对端挂了）只在抛出那一刻确定；
 *  挪到 catch 里靠 message 正则反推，迟早在某个新错误形状上猜错。
 *  `retryable` 只表示「重放是安全的」——调用方仍要另外确认「本次尝试还没吐过输出」。
 *  （2026-10-23 从 `openai.ts` 搬来这里：三家适配器现在共用同一套流内重试判据，见
 *  `retryableStreamErrorFrame`；只留一份，别让下一支再抄一遍名字表。） */
export class StreamFailure extends Error {
  readonly retryable: boolean;
  constructor(message: string, retryable: boolean) {
    super(message);
    this.name = "StreamFailure";
    this.retryable = retryable;
  }
}

/** 对端把错误**塞进 SSE 体**时的名字表（HTTP 已是 200，状态码那一半失效）。
 *  OpenAI 兼容网关实测用 `server_error`（即 502）；Anthropic 用 `overloaded_error` / `api_error`；
 *  Gemini 用 `UNAVAILABLE` / `RESOURCE_EXHAUSTED` / `INTERNAL` / `DEADLINE_EXCEEDED`（大写）。
 *  只收「重放有意义的」：`invalid_request_error`、`authentication_error`、`permission_error`
 *  这类是请求本身的问题，重放只会再错一次并白烧预算。 */
const RETRYABLE_STREAM_ERROR_NAMES: ReadonlySet<string> = new Set([
  "server_error", "overloaded_error", "rate_limit_exceeded", "rate_limit_error", "timeout",
  "api_error", "unavailable", "resource_exhausted", "internal", "deadline_exceeded",
]);

/** 三家流内 error 帧的统一判据（数值优先，名字其次）。
 *  `status` / `code` / `type` 都可能带数值，也都可能是**字符串形式的数值**（OpenRouter 实测
 *  `"type": "502"`，Gemini 用 `"code": 429`）⇒ 两处都取、都转数。名字只补「没有数值」那一半。 */
export function retryableStreamErrorFrame(fields: {
  readonly names?: readonly (string | number | null | undefined)[];
  readonly messages?: string;
}): boolean {
  const values = fields.names ?? [];
  for (const value of values) {
    const numeric = typeof value === "number" ? value : Number(value);
    if (Number.isFinite(numeric) && retryableStatus(numeric)) return true;
  }
  for (const value of values) {
    if (typeof value !== "string") continue;
    if (RETRYABLE_STREAM_ERROR_NAMES.has(value.trim().toLowerCase())) return true;
  }
  return false;
}

/** 流内 catch 处的统一判据：`StreamFailure` 自己声明；未知形状按可重放（网络抖动那一类）。 */
export function retryableStreamFailure(err: unknown): boolean {
  return err instanceof StreamFailure ? err.retryable : true;
}

/** 指数退避 + full jitter（AWS 口径）：同批 worker 齐步重试会把限流窗口二次打满。
 *  attempt 从 1 起 ⇒ 第 1 次重试上限 base、第 2 次 2·base、第 3 次 4·base，封顶 capMs。 */
export function backoffMs(attempt: number, baseMs: number, capMs: number, rand: () => number): number {
  const cap = Math.min(capMs, baseMs * Math.pow(2, Math.max(0, attempt - 1)));
  return Math.max(0, Math.min(cap, Math.floor(cap * rand())));
}

export interface EstablishOptions {
  label: string;
  url: string;
  /** 不含 signal 的请求参数——signal 由本函数按「看门狗 + 会话取消」合成。 */
  init: RequestInit;
  fetchImpl?: typeof fetch;
  stallMs?: number;
  callerSignal?: AbortSignal;
  /** 总尝试次数（含首次）。缺省 3。 */
  attempts?: number;
  baseDelayMs?: number;
  capDelayMs?: number;
  sleep?: (ms: number) => Promise<void>;
  rand?: () => number;
  /** 每次重试的可见回调（fail-visible：静默重试等于把故障藏起来）。 */
  onRetry?: (info: { attempt: number; status: number | null; delayMs: number; reason: string }) => void;
}

export interface Established {
  res: Response;
  /** 成功建连后**交还给调用方**的看门狗——流体生命周期仍归调用方管（bump / dispose）。 */
  guard: StallGuard;
}

/** 错误正文只用于 300 字符诊断；读取有限前缀，并在每块进展上续期。
 *  长度头超限仍要保留前缀，所以不走会按 Content-Length 拒绝的 readBodyCapped。 */
async function readErrorPrefix(res: Response, guard: StallGuard): Promise<string> {
  guard.bump();
  const reader = res.body?.getReader();
  if (!reader) return res.text();
  const decoder = new TextDecoder();
  const maxBytes = 4_096;
  let bytes = 0;
  let text = "";
  try {
    while (bytes < maxBytes) {
      const { done, value } = await reader.read();
      if (done) break;
      if (value.byteLength > 0) guard.bump();
      const prefix = value.subarray(0, maxBytes - bytes);
      text += decoder.decode(prefix, { stream: true });
      bytes += prefix.byteLength;
    }
    return text + decoder.decode();
  } finally {
    void reader.cancel().catch(() => {});
    reader.releaseLock();
  }
}

/** 建立一次流式请求，只重试「响应体尚未被消费」的失败：网络错误 / 429 / 5xx。
 *  一旦 `res.ok` 就交回调用方，**绝不重放**——流已开始产出后重试会把同一轮 delta 吐两遍
 *  （比失败更糟：模型看到重复内容）。
 *  停滞（`guard.stalled()`）不重试：那是 60s 量级的等待，重试三次等于白挂三分钟，
 *  直接把可读原因抛回上层（stallGuard 以 Error 作 abort reason，上层无需翻译）。
 *  调用方取消也不重试（那是用户意图，不是故障）。 */
export async function establishStream(o: EstablishOptions): Promise<Established> {
  const doFetch = o.fetchImpl ?? fetch;
  const attempts = Math.max(1, Math.floor(o.attempts ?? 3));
  const baseMs = o.baseDelayMs ?? 500;
  const capMs = o.capDelayMs ?? 8_000;
  const sleep = o.sleep ?? (async (ms: number): Promise<void> => {
    try { await delay(ms, o.callerSignal); }
    catch (err) {
      // timers/promises 抛包装后的 AbortError；向上保留会话的原始取消原因。
      o.callerSignal?.throwIfAborted();
      throw err;
    }
  });
  const rand = o.rand ?? Math.random;
  for (let attempt = 1; ; attempt++) {
    o.callerSignal?.throwIfAborted();
    const guard = stallGuard(o.stallMs ?? DEFAULT_STALL_MS, o.label);
    const signal = o.callerSignal !== undefined ? AbortSignal.any([guard.signal, o.callerSignal]) : guard.signal;
    let res: Response;
    try {
      // 不跟随重定向：undici 默认 follow，而 provider 请求带完整会话正文；对端一个
      // `307 Location: http://169.254.169.254/...` 就能把正文发到内网（web_fetch 早已逐跳校验）。
      // 重定向端点请把 baseURL 直接配成最终地址。
      res = await doFetch(o.url, { redirect: "manual", ...o.init, signal });
    } catch (err) {
      guard.dispose(); // 建连阶段失败：看门狗不能留下
      const cancelled = o.callerSignal?.aborted === true || (err instanceof Error && err.name === "AbortError");
      if (cancelled || guard.stalled() || attempt >= attempts) throw err;
      const delay = backoffMs(attempt, baseMs, capMs, rand);
      o.onRetry?.({ attempt, status: null, delayMs: delay, reason: err instanceof Error ? err.message : String(err) });
      o.callerSignal?.throwIfAborted();
      await sleep(delay);
      continue;
    }
    if (res.ok) return { res, guard };
    let text = "";
    try { text = await readErrorPrefix(res, guard); }
    catch { /* 正文读取失败时仍保留 HTTP 状态；取消和停滞由下面的 signal 还原。 */ }
    finally { guard.dispose(); }
    if (res.status >= 300 && res.status < 400) {
      throw new Error(
        `${o.label} 端点返回 HTTP ${String(res.status)} 重定向（已拒绝跟随：防止把请求正文发往未校验的地址；` +
        "请把 baseURL 直接指向最终地址）",
      );
    }
    if (!retryableStatus(res.status) || attempt >= attempts || o.callerSignal?.aborted === true || guard.stalled()) {
      signal.throwIfAborted();
      // 文案与既有三家逐字同构（多条测 / 门禁按 `${label} 请求失败 HTTP <status>` 断言）
      throw new Error(`${o.label} 请求失败 HTTP ${String(res.status)}: ${text.slice(0, 300)}`);
    }
    const headerMs = retryAfterMs(res.headers?.get?.("retry-after") ?? null, Date.now(), capMs);
    const delay = headerMs ?? backoffMs(attempt, baseMs, capMs, rand);
    o.onRetry?.({ attempt, status: res.status, delayMs: delay, reason: text.slice(0, 200) });
    o.callerSignal?.throwIfAborted();
    await sleep(delay);
  }
}

// OpenAI Chat Completions 原生适配器（SSE 流式 + 非流式），由原 glm.ts 泛化而来：
// baseURL / model / 额外 body 参数（extraBody）/ 环境变量名均可配，GLM 是它的一组预设（见 glm.ts）。
// 解码规则与迁移前逐字一致：增量在 choices[0].delta.content；tool_calls 按 index 跨块累积
//（id 首块、name 非空即记、arguments 拼接）；末 chunk 带 usage（后到覆盖）；data: [DONE] 结束。
import { createHash, randomUUID } from "node:crypto";
import { DEFAULT_STALL_MS } from "../net";
import { backoffMs, establishStream, retryableStreamErrorFrame, retryableStreamFailure, StreamFailure, waitRetryDelay } from "./retry";
import { turnStopMissingEvent, turnTruncatedEvent } from "./stop-reason";
import type { ModelOutput, ProviderContentImage, ProviderMessage, ProviderMessageWithImage, ProviderToolSpec } from "./index";
import type { RequestMeter, RequestCategory, MeterUsage, RequestOutcome } from "../agent/metering";

/** `StreamFailure` 与流内 error 帧的判据已搬到 `retry.ts`（2026-10-23）：三家适配器共用同一套，
 *  名字表与「数值优先」的读法只留一份。这里再导出，保持既有 import 路径不变。 */
export { StreamFailure } from "./retry";

export type OpenAiMessage = ProviderMessage;
export type OpenAiToolSpec = ProviderToolSpec;

export interface OpenAiOptions {
  /** 缺省读 process.env[apiKeyEnv ?? "OPENAI_API_KEY"]。 */
  apiKey?: string;
  /** 缺失 key 时的环境变量名（进错误消息），缺省 OPENAI_API_KEY。 */
  apiKeyEnv?: string;
  model?: string;
  /** model 的环境变量名，缺省 OPENAI_MODEL。 */
  modelEnv?: string;
  /** model 的最终缺省值，缺省 gpt-4o-mini。 */
  defaultModel?: string;
  /** 端点：base（`https://host/v1`）或完整 URL 都行，缺 `/chat/completions` 会补齐（见 chatCompletionsEndpoint）。 */
  baseURL?: string;
  /** baseURL 的环境变量名，缺省 OPENAI_BASE_URL。 */
  baseURLEnv?: string;
  /** baseURL 的最终缺省值，缺省 OpenAI 官方端点。 */
  defaultBaseURL?: string;
  /** 额外 body 参数（GLM 预设传 tool_stream:true）；在 stream/model/messages 之后合并。 */
  extraBody?: Record<string, unknown>;
  /** 反向验证开关：false = 非流式（整段回复只算 1 个 delta），缺省 true。 */
  stream?: boolean;
  /** 错误消息前缀（GLM 预设为 "GLM"），缺省 "OpenAI"。 */
  label?: string;
  /** 单测注入点（缺省全局 fetch）。 */
  fetchImpl?: typeof fetch;
  /** 停滞守卫静默窗口 ms（根因 4）；缺省 60s，<=0 关闭守卫。 */
  stallTimeoutMs?: number;
  /** 思考档位（"low"|"medium"|"high"）：非空则写 body.reasoning_effort。
   *  传的是**档位名**而不是数值——OpenAI 兼容族收的就是这个名字（DeepSeek 的 /models 自述里
   *  `effort.supported_levels` 写明的也是这些名字）。undefined = 逐字旧行为（不出现这个字段）。 */
  reasoningEffort?: string;
  /** Opt-in wire-boundary accounting; never stores payload/key text. */
  metering?: { meter: RequestMeter; category: RequestCategory };
}

interface DeltaToolCall {
  index: number;
  id?: string;
  function?: { name?: string; arguments?: string };
}

interface ChatChunk {
  id?: string;
  choices?: {
    delta?: {
      content?: string;
      /** 推理正文：DeepSeek 系用 `reasoning_content`，OpenAI o 系用 `reasoning`。 */
      reasoning_content?: string;
      reasoning?: string;
      tool_calls?: DeltaToolCall[];
    };
    message?: { content?: string; reasoning_content?: string; tool_calls?: DeltaToolCall[] };
    finish_reason?: string | null;
  }[];
  usage?: { prompt_tokens?: number; completion_tokens?: number; prompt_tokens_details?: { cached_tokens?: number }; completion_tokens_details?: { reasoning_tokens?: number }; cache_creation_input_tokens?: number } | null;
  // OpenAI 流中段错误事件（如内容审查），出现即按协议错误抛出
  error?: { message?: string; type?: string; code?: string } | null;
}

function parseArgs(raw: string | undefined, label: string): Record<string, unknown> {
  if (!raw || raw.trim() === "") return {};
  // 参数 JSON 损坏属协议级异常，fail loud，不静默吞掉
  const parsed = JSON.parse(raw) as unknown;
  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    throw new Error(`${label} tool_call arguments 不是对象: ${raw.slice(0, 100)}`);
  }
  return parsed as Record<string, unknown>;
}

/** 计量口径统一：非数 / 负数一律算「未上报」(null)，绝不折算成 0——缺报与零命中是两件事。 */
function tokenCount(v: unknown): number | null {
  return typeof v === "number" && Number.isFinite(v) && v >= 0 ? v : null;
}

function toUsage(u: NonNullable<ChatChunk["usage"]>): ModelOutput & { type: "usage" } {
  // prompt_tokens 本身含缓存命中量 → 事件口径已一致；这里只是把分块透出，让命中率可见（缺报不落 0）
  const read = tokenCount(u.prompt_tokens_details?.cached_tokens);
  const write = tokenCount(u.cache_creation_input_tokens);
  const reasoning = tokenCount(u.completion_tokens_details?.reasoning_tokens);
  return {
    type: "usage",
    inputTokens: u.prompt_tokens ?? 0,
    outputTokens: u.completion_tokens ?? 0,
    ...(read !== null ? { cacheReadInputTokens: read } : {}),
    ...(write !== null ? { cacheWriteInputTokens: write } : {}),
    ...(reasoning !== null ? { reasoningOutputTokens: reasoning } : {}),
  };
}

/** 带图消息的 wire 形状：content 从字符串换成 OpenAI 的 parts 数组。
 *  **纯文本消息不走这里**——它在 toWireMessages 里逐字保持 `content: "..."`，
 *  既不让第三方 OpenAI 兼容网关看到陌生形状，也不动前缀缓存的前缀匹配。 */
function toWireImageMessage(m: OpenAiMessage, parts: readonly ProviderContentImage[]): unknown {
  const blocks: unknown[] = [];
  if (m.content !== null && m.content !== "") blocks.push({ type: "text", text: m.content });
  for (const p of parts) {
    if (p.type !== "image") continue;
    blocks.push({ type: "image_url", image_url: { url: p.dataUrl } });
  }
  if (blocks.length === 0) return { role: m.role, content: m.content };
  return {
    role: m.role,
    content: blocks,
    ...(m.tool_calls ? { tool_calls: m.tool_calls } : {}),
    ...(m.tool_call_id !== undefined ? { tool_call_id: m.tool_call_id } : {}),
  };
}

/** 一条消息的 wire 形状（识图那一支在这里分叉）。 */
function toWireMessage(m: OpenAiMessage, reasoningSource?: string): unknown {
  const parts = (m as ProviderMessageWithImage).contentParts;
  const native = m.role === "assistant" && reasoningSource !== undefined && m.reasoning?.source === reasoningSource
    ? { reasoning_content: m.reasoning.content } : {};
  if (parts !== undefined && parts.length > 0) return { ...(toWireImageMessage(m, parts) as object), ...native };
  return {
    role: m.role,
    content: m.content,
    ...(m.tool_calls ? { tool_calls: m.tool_calls } : {}),
    ...(m.tool_call_id !== undefined ? { tool_call_id: m.tool_call_id } : {}),
    ...native,
  };
}

/** 识图消息表（纯函数，供判卷直接钉 wire 形状）。 */
export function toOpenAiWireMessages(messages: OpenAiMessage[], reasoningSource?: string): unknown[] {
  return messages.map(message => toWireMessage(message, reasoningSource));
}

function toWireTools(tools: OpenAiToolSpec[]): unknown[] {
  return tools.map((t) => ({
    type: "function",
    function: { name: t.name, ...(t.description ? { description: t.description } : {}), parameters: t.parameters },
  }));
}

/** 自建/兼容网关的端点归一：给的可以是 base（`https://host/v1`），也可以是完整 endpoint。
 *  两侧代价不对称——按原样发一个 base 出去必然 404，而重复拼 `/chat/completions` 同样打不通。
 *  后缀已经是它就原样用（GLM_ENDPOINT 那种写法保持逐字可用），否则补齐。 */
export function chatCompletionsEndpoint(base: string): string {
  const trimmed = base.replace(/\/+$/, "");
  return trimmed.endsWith("/chat/completions") ? trimmed : `${trimmed}/chat/completions`;
}

/** 流式一轮对话：把 SSE 增量转成事件 —— delta.content → assistant_delta、
 *  delta.tool_calls → 累积成 tool_call 事件（流末按 index 稳定吐出）、末 chunk usage → usage 事件。 */
export async function* streamOpenAI(
  messages: OpenAiMessage[],
  opts: OpenAiOptions = {},
  tools?: OpenAiToolSpec[],
  call?: { signal?: AbortSignal },
): AsyncGenerator<ModelOutput> {
  const label = opts.label ?? "OpenAI";
  const envName = opts.apiKeyEnv ?? "OPENAI_API_KEY";
  const apiKey = opts.apiKey ?? process.env[envName];
  if (!apiKey) throw new Error(`${envName} 未设置（key 只从环境变量读取，不落文件）`);
  const model = opts.model ?? process.env[opts.modelEnv ?? "OPENAI_MODEL"] ?? opts.defaultModel ?? "gpt-4o-mini";
  const endpoint = chatCompletionsEndpoint(
    opts.baseURL ?? process.env[opts.baseURLEnv ?? "OPENAI_BASE_URL"] ?? opts.defaultBaseURL ?? "https://api.openai.com/v1",
  );
  const stream = opts.stream ?? true;
  const rawFetch = opts.fetchImpl ?? fetch;
  // 缺失原生 id 时，序号只在这一逻辑请求内有效；重试沿用同一前缀，新请求不得碰撞。
  const toolRequestScope = randomUUID();

  const reasoningSource = createHash("sha256").update(endpoint + "\0" + model).digest("hex");
  const nativeDeepSeek = new URL(endpoint).hostname === "api.deepseek.com";
  const body: Record<string, unknown> = { model, messages: toOpenAiWireMessages(messages, reasoningSource), stream };
  // C8（审查 P2）：流式计量——OpenAI 兼容端点默认不回 usage，须显式开启 stream_options.include_usage，
  // 否则流式会话 token 恒 0（成本闸/用量面板全失真）。extraBody 仍可覆盖（自建网关不兼容时）。
  if (stream) body.stream_options = { include_usage: true };
  if (opts.reasoningEffort === "off") {
    if (nativeDeepSeek) body.thinking = { type: "disabled" };
  } else if (opts.reasoningEffort !== undefined && opts.reasoningEffort !== "") {
    body.reasoning_effort = opts.reasoningEffort;
    if (nativeDeepSeek) body.thinking = { type: "enabled" };
  }
  if (opts.extraBody) Object.assign(body, opts.extraBody);
  if (tools && tools.length > 0) body.tools = toWireTools(tools);

  // 根因 4：停滞守卫改由 establishStream 逐次新建（静默窗口，不是总时长）；
  // 成功建连后交回本函数继续管流体（bump / dispose）。
  const serializedBody = JSON.stringify(body);
  call?.signal?.throwIfAborted();
  const metering = opts.metering;
  let requestId: number | undefined;
  let meterOutcome: RequestOutcome = "failed";
  let meterUsage: Partial<MeterUsage> = {};
  const finishMeter = (outcome: RequestOutcome): void => {
    if (requestId === undefined || metering === undefined) return;
    metering.meter.finishRequest(requestId, outcome, meterUsage);
    requestId = undefined;
  };
  // establishStream 的 HTTP 重试与下方 SSE 重试都在同一发送位置逐笔登记。
  const doFetch: typeof fetch = metering === undefined ? rawFetch : async (input, init) => {
    meterUsage = {};
    meterOutcome = "failed";
    requestId = metering.meter.beginRequest(metering.category, serializedBody);
    try {
      return await rawFetch(input, init);
    } catch (error) {
      finishMeter(call?.signal?.aborted ? "cancelled" : "failed");
      throw error;
    }
  };
  const observeUsage = (u: NonNullable<ChatChunk["usage"]>): void => {
    const input = tokenCount(u.prompt_tokens), read = tokenCount(u.prompt_tokens_details?.cached_tokens);
    // OpenAI/GLM do not report a disjoint cache-write bucket. Do not invent zero.
    const write = tokenCount(u.cache_creation_input_tokens);
    meterUsage = { inputTokens: input !== null ? Math.max(0, input - (read ?? 0) - (write ?? 0)) : null,
      outputTokens: tokenCount(u.completion_tokens), cacheReadInputTokens: read, cacheWriteInputTokens: write };
  };
  try {
  /* 流内重试（2026-09-30 实测动因）：`establishStream` 只管到「响应体尚未被消费」那一段，
   * 而对端把 5xx **塞进 SSE 体里**（HTTP 200 + 一帧 `{"error":{"type":"502",…}}`）时它管不着。
   * 实测 OpenRouter 的 `502 Provider returned an empty response` 正是这个形状：
   * 简单请求 200，多轮工具调用一到第 3~9 轮必挂，连续 7 次把整轮任务打死。
   *
   * **安全边界**：只有本次尝试「一个输出都还没吐出去」时才允许重放。
   * 一旦吐过 delta/tool_call，重放会把同一轮内容吐两遍——那比失败更糟（模型看到重复内容），
   * 建连段那条不变量（上面写着「绝不重放」）正是为这个立的。
   * 判据三件缺一不可：① 没吐过输出；② 还有次数；③ 不是调用方取消。 */
  // 非流式分支（摘要器 / 反向验证用）：整段回复转成同一条事件管线，delta 只有 1 个。
  // 它**不参与流内重试**：没有 delta 边界可言，失败即整轮失败，重放语义归调用方定。
  if (!stream) {
    const estNs = await establishStream({
      label,
      url: endpoint,
      init: {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${apiKey}` },
        body: serializedBody,
      },
      fetchImpl: doFetch,
      onRetry: () => finishMeter("failed"),
      stallMs: opts.stallTimeoutMs ?? DEFAULT_STALL_MS,
      ...(call?.signal !== undefined ? { callerSignal: call.signal } : {}),
    });
    const resNs = estNs.res;
    try {
      const data = (await resNs.json()) as ChatChunk;
      if (data.usage) observeUsage(data.usage);
      const callId = data.id ?? "a-0";
      const msg = data.choices?.[0]?.message;
      const nativeReasoning = typeof msg?.reasoning_content === "string" && msg.reasoning_content !== "";
      if (nativeReasoning) yield { type: "thinking_delta", callId, text: msg!.reasoning_content!, reasoning: { id: toolRequestScope, source: reasoningSource } };
      if (msg?.content) yield { type: "assistant_delta", callId, text: msg.content };
      for (const [index, c] of (msg?.tool_calls ?? []).entries()) {
        yield {
          type: "tool_call",
          id: c.id ?? `call-${toolRequestScope}-${String(c.index ?? index)}`,
          name: c.function?.name ?? "",
          args: parseArgs(c.function?.arguments, label),
          ...(nativeReasoning ? { reasoningId: toolRequestScope } : {}),
        };
      }
      if (data.usage) yield toUsage(data.usage);
      // 非流式分支同一家、同一个字段：整段回复一样会被 length 砍断。
      // 这条尤其不能省——本分支唯一的真调用者是压缩摘要器，而摘要正是长任务上旧事件被排除后
      // 唯一的存活通道；一份砍了一半的摘要落进记录，比不落更坏（它会以「完整结论」的形态被读到）。
      const truncated = turnTruncatedEvent(callId, data.choices?.[0]?.finish_reason, data.usage?.completion_tokens);
      if (truncated) yield truncated;
      const stopMissing = turnStopMissingEvent(callId, data.choices?.[0]?.finish_reason, data.usage?.completion_tokens);
      if (stopMissing) yield stopMissing;
      meterOutcome = "ok";
    } finally {
      estNs.guard.dispose();
    }
    return;
  }

  const STREAM_ATTEMPTS = 3;
  const streamOnce = async function* (): AsyncGenerator<ModelOutput, void, undefined> {
    let attempt = 0;
    let emitted = false;
    for (;;) {
      attempt += 1;
      const est = await establishStream({
        label,
        url: endpoint,
        init: {
          method: "POST",
          headers: { "Content-Type": "application/json", Authorization: `Bearer ${apiKey}` },
          body: serializedBody,
        },
        fetchImpl: doFetch,
        onRetry: () => finishMeter("failed"),
        stallMs: opts.stallTimeoutMs ?? DEFAULT_STALL_MS,
        ...(call?.signal !== undefined ? { callerSignal: call.signal } : {}),
        ...(attempt > 1 ? { attempts: 1 } : {}), // 建连段那一层重试上一轮已付过
      });
      const res2 = est.res;
      if (!res2.body) {
        est.guard.dispose();
        throw new Error(`${label} 流式响应缺少 body`);
      }
      const reader2 = res2.body.getReader();
      // 每次尝试单独解码；半个 UTF-8 字符、buf 与 tool_call 分片都不能带入下一轮。
      const decoder = new TextDecoder();
      let buf2 = "";
      let finished2 = false;
      let callId2 = "a-0";
      let nativeReasoning2 = false;
      const pending2 = new Map<number, { id?: string; name: string; args: string }>();
      let usage2: (ModelOutput & { type: "usage" }) | null = null;
      let finishReason2: string | null | undefined;
      let retryError: unknown;
      try {
        while (!finished2) {
          const { done, value } = await reader2.read();
          if (done) break;
          est.guard.bump();
          buf2 += decoder.decode(value, { stream: true });
          let nl: number;
          while ((nl = buf2.indexOf("\n")) >= 0) {
            const line = buf2.slice(0, nl).trim();
            buf2 = buf2.slice(nl + 1);
            if (!line.startsWith("data:")) continue;
            const payload = line.slice(5).trim();
            if (!payload) continue;
            if (payload === "[DONE]") { finished2 = true; break; }
            let chunk: ChatChunk;
            try {
              chunk = JSON.parse(payload) as ChatChunk;
            } catch {
              if (!payload.startsWith("{")) continue; // 心跳/注释/网关杂帧：容忍
              throw new StreamFailure(`${label} SSE 帧损坏（半帧截断？）：JSON 解析失败，拒绝静默丢字`, false);
            }
            if (chunk.error) {
              const e = chunk.error;
              const named = typeof e.type === "string" ? e.type : undefined;
              // 数值可能落在 `type` 也可能落在 `code`，且可能是字符串形式（OpenRouter 实测
              // `"type": "502"`）。判据住 `retry.ts`：三家共用一份名字表与「数值优先」的读法。
              throw new StreamFailure(
                `${label} 流错误 ${named ?? e.code ?? "unknown"}: ${e.message ?? ""}`,
                retryableStreamErrorFrame({ names: [e.type, e.code] }),
              );
            }
            if (chunk.id) callId2 = chunk.id;
            if (chunk.usage) { usage2 = toUsage(chunk.usage); observeUsage(chunk.usage); }
            const fr = chunk.choices?.[0]?.finish_reason;
            if (fr) finishReason2 = fr;
            const delta = chunk.choices?.[0]?.delta;
            // 推理增量（`reasoning_content` / `reasoning`）→ **thinking_delta**（与正文分开的事件）。
            // 2026-10-07 之前这里刻意不读（怕污染转录），现在用户要求显示思考过程：
            // 关键是**走独立事件**而不是并进 content —— 转录里正文仍是正文，思考单独一段，
            // 回放与转录都干净（思考块在多数家本就不可回传）。
            const thinking = delta?.reasoning_content ?? delta?.reasoning;
            if (typeof thinking === "string" && thinking !== "") {
              emitted = true;
              if (typeof delta?.reasoning_content === "string") nativeReasoning2 = true;
              yield { type: "thinking_delta", callId: callId2, text: thinking,
                ...(typeof delta?.reasoning_content === "string" ? { reasoning: { id: toolRequestScope, source: reasoningSource } } : {}) };
            }
            if (delta?.content) {
              emitted = true;
              yield { type: "assistant_delta", callId: callId2, text: delta.content };
            }
            if (delta?.tool_calls) {
              emitted = true;
              for (const tc of delta.tool_calls) {
                const acc = pending2.get(tc.index) ?? { id: undefined, name: "", args: "" };
                if (tc.id) acc.id = tc.id;
                if (tc.function?.name) acc.name = tc.function.name;
                if (tc.function?.arguments) acc.args += tc.function.arguments;
                pending2.set(tc.index, acc);
              }
            }
          }
        }
        // 收尾三件，顺序与原实现逐字一致：
        // ① truncated 必须在 tool_call 冲刷**之前**（被截断的 write_file 参数会让 parseArgs 抛，
        //    排在其后这条记录就永远发不出去——而那恰是最常见的截断形状）；
        // ② 累积的 tool_call 按 index 稳定排序后吐出；
        // ③ usage 最后。
        const truncated = turnTruncatedEvent(callId2, finishReason2, usage2?.outputTokens ?? null);
        if (truncated) yield truncated;
        // 与 truncated 同一位置、同一理由：先于 tool_call 冲刷与 usage（args 解析若抛，
        // 这条证据不能跟着陪葬）。两者互斥：有原文走 truncated，没原文走这一枚。
        const stopMissing = turnStopMissingEvent(callId2, finishReason2, usage2?.outputTokens ?? null);
        if (stopMissing) yield stopMissing;
        const ordered = [...pending2.entries()].sort((a, b) => a[0] - b[0]);
        for (const [index, acc] of ordered) {
          yield {
            type: "tool_call",
            id: acc.id ?? `call-${toolRequestScope}-${String(index)}`,
            name: acc.name,
            args: parseArgs(acc.args, label),
            ...(nativeReasoning2 ? { reasoningId: toolRequestScope } : {}),
          };
        }
        if (usage2) yield usage2;
        return;
      } catch (err) {
        finishMeter(call?.signal?.aborted ? "cancelled" : "failed");
        const cancelled = call?.signal?.aborted === true;
        // 不可重放的失败（协议级：帧损坏 / 非 5xx 的 error 帧）立刻抛，不拿它去打转。
        // stall 守卫触发也不重放：重放会把静默窗当网络抖动再烧一遍全长超时。
        const stalledByGuard = est.guard.stalled();
        const retryable = stalledByGuard ? false : retryableStreamFailure(err);
        if (emitted || attempt >= STREAM_ATTEMPTS || cancelled || !retryable) throw err;
        retryError = err;
      } finally {
        // 包括消费者在 yield 处提前 return；重试退避前也先回收本次响应。
        est.guard.dispose();
        void reader2.cancel().catch(() => {});
        reader2.releaseLock();
      }
      const delay = backoffMs(attempt, 300, 2_000, Math.random);
      console.warn(
        `[${label}] 流内失败（第 ${String(attempt)} 次，尚未产出任何输出）⇒ ${String(delay)}ms 后重试：`
        + (retryError instanceof Error ? retryError.message : String(retryError)),
      );
      try {
        await waitRetryDelay(delay, call?.signal);
      } catch (error) {
        call?.signal?.throwIfAborted();
        throw error;
      }
    }
  };
  // 流式分支的全部产出（含流内重试与收尾三件）都在 streamOnce 里，这里只负责调用。
  yield* streamOnce();
  meterOutcome = "ok";
  } finally {
    finishMeter(call?.signal?.aborted ? "cancelled" : meterOutcome);
  }
}

// Anthropic Messages API 原生适配器（https://docs.anthropic.com/en/api/messages-streaming）。
// SSE 事件序：message_start → 每内容块 content_block_start / 一条或多条 content_block_delta
//（text_delta 或 input_json_delta.partial_json）/ content_block_stop（每块带 index）→
// 一条或多条 message_delta → message_stop；ping 与未知事件优雅跳过；error 事件转可读错误。
// message_delta 里的 usage 是【累计值】——直接取最后一条，不得跨事件累加。
// 解析直接消费 Anthropic 原生字段（content_block_delta.delta.text_delta 等），
// 不经过任何 OpenAI 中间格式。
import { randomUUID } from "node:crypto";
import { DEFAULT_STALL_MS, type StallGuard } from "../net";
import { establishStream } from "./retry";
import { turnStopMissingEvent, turnTruncatedEvent } from "./stop-reason";
import type { ModelOutput, ProviderContentImage, ProviderMessage, ProviderMessageWithImage, ProviderToolSpec } from "./index";

export interface AnthropicOptions {
  /** 缺省读 process.env.ANTHROPIC_API_KEY。 */
  apiKey?: string;
  /** 缺失 key 时的环境变量名（进错误消息），缺省 ANTHROPIC_API_KEY。 */
  apiKeyEnv?: string;
  model?: string;
  /** max_tokens 为 Anthropic 必填字段（单轮输出上限），缺省 4096。 */
  maxTokens?: number;
  /** 思考预算（token）：非空则加 body.thinking = {type:"enabled", budget_tokens}。
   *  Anthropic 要求 max_tokens **严格大于** budget_tokens，故调用处会一起把 maxTokens 抬上去。 */
  thinkingBudget?: number;
  baseURL?: string;
  /** anthropic-version 请求头，缺省 2023-06-01。 */
  version?: string;
  /** 单测注入点（缺省全局 fetch）。 */
  fetchImpl?: typeof fetch;
  /** 错误消息前缀，缺省 "Anthropic"。 */
  label?: string;
  /** 停滞守卫静默窗口 ms（根因 4）；缺省 60s，<=0 关闭守卫。 */
  stallTimeoutMs?: number;
  /** prompt 缓存断点（A1 写侧）：在**静态段**尾上打 `cache_control:{type:"ephemeral"}`——
   *  末个 tool 与末个 system 块各一处（断点分层级联：工具条目恒命中，tools+system 条目只在
   *  system 未变时命中；本仓的记忆/地图随轮变化，落在 system 串内，故第二条目会周期性重写，
   *  这是排布事实不是本开关的副作用——按用户裁决「只标静态段，不动排布」）。
   *  缺省 false = 请求体逐字不变（含 `system` 仍为整串）。 */
  promptCache?: boolean;
}

interface AnthropicSseEvent {
  type?: string;
  message?: { id?: string; usage?: { input_tokens?: number; output_tokens?: number; cache_read_input_tokens?: number; cache_creation_input_tokens?: number } };
  content_block?: { type?: string; id?: string; name?: string; input?: unknown };
  index?: number;
  delta?: {
    type?: string;
    text?: string;
    /** thinking_delta 子类型的思考文本（budget 开启时才有）。 */
    thinking?: string;
    partial_json?: string;
    stop_reason?: string | null;
  };
  usage?: { input_tokens?: number; output_tokens?: number; cache_read_input_tokens?: number; cache_creation_input_tokens?: number };
  error?: { type?: string; message?: string };
}

function parseArgs(raw: string, label: string): Record<string, unknown> {
  if (raw.trim() === "") return {};
  // 分片拼接后的参数 JSON 损坏属协议级异常，fail loud，不静默吞掉
  const parsed = JSON.parse(raw) as unknown;
  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    throw new Error(`${label} tool_use input 不是对象: ${raw.slice(0, 100)}`);
  }
  return parsed as Record<string, unknown>;
}

// ProviderMessage → Anthropic wire 格式：system 抽成顶层 system 参数；
// user/assistant 文本；assistant 的 tool_calls → tool_use 块；tool 结果（连续合并为一条
// user 消息）→ tool_result 块。全部按 Anthropic 官方 content-block 结构原生构造。
export function toAnthropicBody(
  messages: ProviderMessage[],
  opts: { model: string; maxTokens: number; stream: boolean; promptCache?: boolean; thinkingBudget?: number },
  tools?: ProviderToolSpec[],
): Record<string, unknown> {
  const systemParts: string[] = [];
  const wire: { role: "user" | "assistant"; content: unknown }[] = [];
  const pendingToolResults: Record<string, unknown>[] = [];
  const flushToolResults = (): void => {
    if (pendingToolResults.length === 0) return;
    wire.push({ role: "user", content: pendingToolResults.splice(0) });
  };
  for (const m of messages) {
    if (m.role === "system") {
      if (m.content) systemParts.push(m.content);
      continue;
    }
    if (m.role === "tool") {
      pendingToolResults.push({ type: "tool_result", tool_use_id: m.tool_call_id ?? "", content: m.content ?? "" });
      continue;
    }
    flushToolResults();
    if (m.role === "assistant") {
      const blocks: Record<string, unknown>[] = [];
      if (m.content) blocks.push({ type: "text", text: m.content });
      for (const tc of m.tool_calls ?? []) {
        let input: unknown = {};
        try {
          input = tc.function.arguments.trim() === "" ? {} : (JSON.parse(tc.function.arguments) as unknown);
        } catch {
          input = {}; // 历史里损坏的参数按空 input 回传（原始请求已 fail loud 过）
        }
        blocks.push({ type: "tool_use", id: tc.id, name: tc.function.name, input });
      }
      wire.push({ role: "assistant", content: blocks.length > 0 ? blocks : m.content ?? "" });
      continue;
    }
    wire.push({ role: "user", content: toAnthropicUserContent(m) });
  }
  flushToolResults();

/** user 消息的 content：带图片时换成 Anthropic 的 blocks 数组（text + image 混排）。
 *  纯文本逐字保持字符串——旧形状不变，前缀缓存与网关兼容性都不动。 */
function toAnthropicUserContent(m: ProviderMessage): unknown {
  const parts = (m as ProviderMessageWithImage).contentParts;
  if (parts === undefined || parts.length === 0) return m.content ?? "";
  const blocks: Record<string, unknown>[] = [];
  if (m.content !== null && m.content !== "") blocks.push({ type: "text", text: m.content });
  for (const p of parts as readonly ProviderContentImage[]) {
    if (p.type !== "image") continue;
    const mm = /^data:(image\/[a-zA-Z0-9.+-]+);base64,(.*)$/s.exec(p.dataUrl);
    // 不是 data URL（外链图片）⇒ 不猜、不静默转成空块：这条消息会 400，让问题暴露在请求上。
    if (mm === null) {
      blocks.push({ type: "text", text: "[image: 非 data URL 的图片引用已忽略——只接受 data:image/...;base64,...]" });
      continue;
    }
    blocks.push({ type: "image", source: { type: "base64", media_type: mm[1], data: mm[2] } });
  }
  return blocks.length > 0 ? blocks : (m.content ?? "");
}
  const body: Record<string, unknown> = {
    model: opts.model,
    max_tokens: opts.maxTokens,
    // 思考档位（§S8）：开了就在请求体里说清楚 —— 预算必须小于 max_tokens，否则上游直接 400。
    // 这里做的是**抬高上限**而不是拒绝：用户要 16k 思考预算时把 max_tokens 顶到 16k+余量，
    // 比抛一句"两个数不合法"更有用（本仓对"用户意图明确、只是数值需要配合"的一律是配合而不是拒）。
    ...(opts.thinkingBudget !== undefined && opts.thinkingBudget > 0
      ? { thinking: { type: "enabled", budget_tokens: opts.thinkingBudget } }
      : {}),
    stream: opts.stream,
    messages: wire,
  };
  // 静态段断点（用户裁决「只标静态段，不动排布」）：
  // ① 末个 tool——本会话内工具表逐字不变，是唯一的纯静态段；
  // ② system 的**首块**=基础提示（composeTurnMessages 恒把 opts.system 放第一位），
  //    其后的记忆/skills/地图随轮变化，一律留在断点之后不参与缓存——
  //    给整串 system 打点会每轮重写缓存条目（写价 1.25×），比不打更贵，故不打。
  // 关闭时逐字旧行为：system 仍是 join 后的整串，且全站零 cache_control 键。
  if (systemParts.length > 0) {
    body.system = opts.promptCache === true
      ? systemParts.map((text, i) => ({ type: "text", text, ...(i === 0 ? { cache_control: { type: "ephemeral" } } : {}) }))
      : systemParts.join("\n\n");
  }
  if (tools && tools.length > 0) {
    const last = tools.length - 1;
    body.tools = tools.map((t, i) => ({
      name: t.name,
      ...(t.description ? { description: t.description } : {}),
      input_schema: t.parameters,
      ...(opts.promptCache === true && i === last ? { cache_control: { type: "ephemeral" } } : {}),
    }));
  }
  return body;
}

/** 流式一轮对话：SSE 事件 → 统一事件流。 */
export async function* streamAnthropic(
  messages: ProviderMessage[],
  opts: AnthropicOptions = {},
  tools?: ProviderToolSpec[],
  call?: { signal?: AbortSignal },
): AsyncGenerator<ModelOutput> {
  const label = opts.label ?? "Anthropic";
  const envName = opts.apiKeyEnv ?? "ANTHROPIC_API_KEY";
  const apiKey = opts.apiKey ?? process.env[envName];
  if (!apiKey) throw new Error(`${envName} 未设置（key 只从环境变量读取，不落文件）`);
  const model = opts.model ?? process.env.ANTHROPIC_MODEL ?? "claude-sonnet-4-5";
  const baseURL = opts.baseURL ?? "https://api.anthropic.com";
  const thinkingBudget = opts.thinkingBudget;
  // Anthropic 的硬要求：max_tokens **严格大于** budget_tokens。用户要 16k 思考预算时，
  // 我们抬上限而不是拒跑 —— 意图是明确的，需要配合的只是数值（本仓对这类一律配合）。
  const baseMaxTokens = opts.maxTokens ?? 4096;
  const maxTokens =
    thinkingBudget !== undefined && thinkingBudget > 0 ? Math.max(baseMaxTokens, thinkingBudget + 4096) : baseMaxTokens;
  const doFetch = opts.fetchImpl ?? fetch;
  const toolRequestScope = randomUUID(); // 缺失原生 id 的序号只在本请求内复用。

  // 根因 4：停滞守卫改由 establishStream 逐次新建（静默窗口，不是总时长），成功建连后交回
  // 本函数继续管流体。建连期失败（429/5xx/网络抖动）按指数退避 + full jitter 重试；
  // 不变量：res.ok 之后绝不重放（流已产出），调用方取消与停滞都不重试。
  let guard: StallGuard | undefined;
  const est = await establishStream({
    label,
    url: `${baseURL}/v1/messages`,
    init: {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-api-key": apiKey,
        "anthropic-version": opts.version ?? "2023-06-01",
      },
      body: JSON.stringify(
        toAnthropicBody(
          messages,
          { model, maxTokens, stream: true, promptCache: opts.promptCache === true, ...(thinkingBudget !== undefined ? { thinkingBudget } : {}) },
          tools,
        ),
      ),
    },
    fetchImpl: doFetch,
    stallMs: opts.stallTimeoutMs ?? DEFAULT_STALL_MS,
    ...(call?.signal !== undefined ? { callerSignal: call.signal } : {}),
  });
  const res = est.res;
  guard = est.guard;
  if (!res.body) {
    guard?.dispose();
    throw new Error(`${label} 流式响应缺少 body`);
  }

  const decoder = new TextDecoder();
  const reader = res.body.getReader();
  let buf = "";
  let callId = "anthropic-a";
  let inputTokens: number | null = null;
  let outputTokens: number | null = null;
  // 缓存分块：Anthropic 的 input_tokens **不含**缓存读写量（与 OpenAI 系 prompt_tokens 含缓存相反），
  // 事件口径统一成「inputTokens = 含缓存总输入」，分块另列（未上报时不落 0）。
  let cacheRead: number | null = null;
  let cacheWrite: number | null = null;
  // 停止原因随 message_delta 到达（可能多条，取最后一条，与 usage 的累计值口径一致）。
  let stopReason: string | null | undefined;
  // 内容块聚合：index → { id, name, json }（input_json_delta 分片跨事件拼接）
  const blocks = new Map<number, { id: string; name: string; json: string }>();

  const handleEvent = function* (event: AnthropicSseEvent): Generator<ModelOutput> {
    switch (event.type) {
      case "message_start": {
        if (event.message?.id) callId = event.message.id;
        if (event.message?.usage?.input_tokens !== undefined) inputTokens = event.message.usage.input_tokens;
        if (event.message?.usage?.cache_read_input_tokens !== undefined) cacheRead = event.message.usage.cache_read_input_tokens;
        if (event.message?.usage?.cache_creation_input_tokens !== undefined) cacheWrite = event.message.usage.cache_creation_input_tokens;
        return;
      }
      case "content_block_start": {
        const cb = event.content_block;
        if (cb?.type === "tool_use" && event.index !== undefined) {
          const seed = cb.input !== undefined && cb.input !== null && Object.keys(cb.input as object).length > 0
            ? JSON.stringify(cb.input)
            : "";
          blocks.set(event.index, { id: cb.id ?? `toolu-${toolRequestScope}-${String(event.index)}`, name: cb.name ?? "", json: seed });
        }
        return;
      }
      case "content_block_delta": {
        const d = event.delta;
        if (d?.type === "text_delta" && d.text) {
          yield { type: "assistant_delta", callId, text: d.text };
        } else if (d?.type === "thinking_delta" && d.thinking) {
          // Claude 的思考块（budget 开启时吐 thinking_delta）→ 独立事件，不并进正文。
          yield { type: "thinking_delta", callId, text: d.thinking };
        } else if (d?.type === "input_json_delta" && d.partial_json && event.index !== undefined) {
          const acc = blocks.get(event.index);
          if (acc) acc.json += d.partial_json; // 分片拼接成完整 JSON（流末 block_stop 时解析）
        }
        // 其余 delta 子类型（signature_delta / citations_delta …）按未知优雅跳过
        return;
      }
      case "content_block_stop": {
        const acc = event.index !== undefined ? blocks.get(event.index) : undefined;
        if (acc) {
          yield { type: "tool_call", id: acc.id, name: acc.name, args: parseArgs(acc.json, label) };
          blocks.delete(event.index as number);
        }
        return;
      }
      case "message_delta": {
        // usage 为累计值：直接覆盖，绝不累加
        if (event.usage?.output_tokens !== undefined) outputTokens = event.usage.output_tokens;
        if (event.usage?.input_tokens !== undefined) inputTokens = event.usage.input_tokens;
        if (event.usage?.cache_read_input_tokens !== undefined) cacheRead = event.usage.cache_read_input_tokens;
        if (event.usage?.cache_creation_input_tokens !== undefined) cacheWrite = event.usage.cache_creation_input_tokens;
        // stop_reason 与 usage 同帧到达。只认真字符串：后续帧可能带 stop_reason:null，
        // 用 !== undefined 会让那个 null 把已经拿到的 max_tokens 抹掉（openai/gemini 侧同用真值判断）。
        if (typeof event.delta?.stop_reason === "string") stopReason = event.delta.stop_reason;
        return;
      }
      case "message_stop":
      case "ping":
        return; // ping 按协议要求优雅跳过
      case "error": {
        const e = event.error ?? {};
        throw new Error(`${label} 流错误 ${e.type ?? "unknown"}: ${e.message ?? ""}`);
      }
      default:
        return; // 未知事件类型：优雅跳过，不抛错
    }
  };

  try {
    let done = false;
    while (!done) {
      const read = await reader.read();
      if (read.done) break;
      guard?.bump(); // 有分片 → 续期（只有完全静默才会到点）
      buf += decoder.decode(read.value, { stream: true });
      let nl: number;
      while ((nl = buf.indexOf("\n")) >= 0) {
        const line = buf.slice(0, nl).trim();
        buf = buf.slice(nl + 1);
        if (!line.startsWith("data:")) continue; // event:/注释/空行跳过（type 以 data JSON 为准）
        const payload = line.slice(5).trim();
        if (!payload) continue;
        // C7（审查 P2）容错边界修正（审查 S1-6）：只对「不是帧的行」容错——注释心跳、
        // 网关塞进来的非 JSON 文本。以 { 开头的真帧 parse 失败不得静默 continue：那意味着
        // 上游把一帧截断了，跳过 = 少一截正文/少一个 tool_call 分片，而流随后正常收尾会让
        // 本轮以「不完整输出」成功收束（loop 无从得知）。同文件 parseArgs 的口径就是协议级
        // 异常 fail loud，这里与之对齐。
        let event: AnthropicSseEvent;
        try {
          event = JSON.parse(payload) as AnthropicSseEvent;
        } catch {
          if (!payload.startsWith("{")) continue; // 心跳/注释/网关杂帧：容忍
          throw new Error(`${label} SSE 帧损坏（半帧截断？）：JSON 解析失败，拒绝静默丢字`);
        }
        yield* handleEvent(event);
      }
    }
    if (inputTokens !== null || outputTokens !== null || cacheRead !== null || cacheWrite !== null) {
      yield {
        type: "usage",
        // Anthropic 的 input_tokens 是「未命中缓存的那一段」，加上读/写缓存才是本次真实输入
        inputTokens: (inputTokens ?? 0) + (cacheRead ?? 0) + (cacheWrite ?? 0),
        outputTokens: outputTokens ?? 0,
        ...(cacheRead !== null ? { cacheReadInputTokens: cacheRead } : {}),
        ...(cacheWrite !== null ? { cacheWriteInputTokens: cacheWrite } : {}),
      };
    }
    // 流正常收尾，但**原因**说这一轮没说完：正文被输出预算/内容策略收走。
    // 上面 C7 那条守的是「半帧被截断」，这里守的是「整帧到齐、模型却没被给够篇幅」——
    // 同一句注释里点名的危害（loop 无从得知），另一支一直没管。
    const truncated = turnTruncatedEvent(callId, stopReason, outputTokens);
    if (truncated) yield truncated;
    // 同位置、互斥：整个流一条 message_delta.stop_reason 都没见到 ⇒ 「不知道它说没说」的证据。
    const stopMissing = turnStopMissingEvent(callId, stopReason, outputTokens);
    if (stopMissing) yield stopMissing;
  } finally {
    guard?.dispose();
    // 消费者提前 break / 出错退出时主动取消 body，否则连接与对端资源一直挂着。
    void reader.cancel().catch(() => {});
  }
}

// Gemini 原生适配器（https://ai.google.dev/api/generate-content）。
// POST {baseURL}/v1beta/models/{model}:streamGenerateContent?alt=sse，鉴权 x-goog-api-key。
// chunk 里 candidates[0].content.parts[]：每项是 { text } 或 { functionCall: { name, args, id? } }；
// 一个 chunk 可含多个 functionCall（并行调用，全部解析成一条条 tool_call）；
// usageMetadata 含 promptTokenCount / candidatesTokenCount / thoughtsTokenCount / totalTokenCount
//（chunk 间累计，末 chunk 为准——直接覆盖不累加）。解析直接消费 Gemini 原生字段，不经 OpenAI 中间格式。
import { randomUUID } from "node:crypto";
import { DEFAULT_STALL_MS, type StallGuard } from "../net";
import { establishStream } from "./retry";
import { turnStopMissingEvent, turnTruncatedEvent } from "./stop-reason";
import type { ModelOutput, ProviderContentImage, ProviderMessage, ProviderMessageWithImage, ProviderToolSpec } from "./index";

export interface GeminiOptions {
  /** 缺省读 process.env.GEMINI_API_KEY。 */
  apiKey?: string;
  /** 缺失 key 时的环境变量名（进错误消息），缺省 GEMINI_API_KEY。 */
  apiKeyEnv?: string;
  model?: string;
  /** 思考预算（token）：非空则加 generationConfig.thinkingConfig.thinkingBudget。 */
  thinkingBudget?: number;
  baseURL?: string;
  /** 单测注入点（缺省全局 fetch）。 */
  fetchImpl?: typeof fetch;
  /** 错误消息前缀，缺省 "Gemini"。 */
  label?: string;
  /** 停滞守卫静默窗口 ms（根因 4）；缺省 60s，<=0 关闭守卫。 */
  stallTimeoutMs?: number;
}

interface GeminiChunk {
  candidates?: {
    content?: {
      parts?: {
        text?: string;
        /** thought=true 的 part 是思考内容（thinkingBudget 开启时才有）。 */
        thought?: boolean;
        functionCall?: { name?: string; args?: Record<string, unknown>; id?: string };
      }[];
      role?: string;
    };
    finishReason?: string | null;
    index?: number;
  }[];
  /** prompt 级拦截（安全策略在整段输入上就判了）时 **candidates 整个缺席**，原因只在这里——
   *  只看 candidates[0].finishReason 的读法会永远撞不到这一支。 */
  promptFeedback?: { blockReason?: string };
  usageMetadata?: {
    promptTokenCount?: number;
    candidatesTokenCount?: number;
    thoughtsTokenCount?: number;
    totalTokenCount?: number;
    /** 本次请求命中**隐式缓存**的那部分输入 token 数（2026-10-05 第 387 页补）。
     *  为什么必须读它：Gemini 2.5+ 的**隐式缓存默认开着**（官方原文：enabled by default for all
     *  Gemini 2.5 and newer models；there is nothing you need to do in order to enable this），
     *  所以不发 `cachedContent` 也会命中。而 `promptTokenCount` **含**缓存那一部分
     *  （官方原文：when `cached_content` is set, this also includes the number of tokens in the
     *  cached content）⇒ 不读这个分块，本地按 token 算的成本就把命中段按**全价输入**计了，
     *  而 Google 实际是打折收的（官方原文：we automatically pass on cost savings）。 */
    cachedContentTokenCount?: number;
  };
  error?: { code?: number; message?: string; status?: string };
}

function parseArgs(args: Record<string, unknown> | undefined, label: string): Record<string, unknown> {
  if (!args || Object.keys(args).length === 0) return {};
  // Gemini 的 functionCall.args 本身就是对象（非 JSON 字符串），直通；只做形状防御
  if (typeof args !== "object" || Array.isArray(args)) {
    throw new Error(`${label} functionCall.args 不是对象`);
  }
  return args;
}

// ProviderMessage → Gemini contents：system 抽成 systemInstruction；user/assistant 文本；
// assistant 的 tool_calls → model 侧 functionCall parts；tool 结果 → user 侧 functionResponse parts
//（连续合并进同一条 contents，name/response 为官方字段）。全部按 Gemini 官方结构原生构造。
export function toGeminiBody(
  messages: ProviderMessage[],
  tools?: ProviderToolSpec[],
  opts: { thinkingBudget?: number } = {},
): Record<string, unknown> {
  const systemParts: string[] = [];
  const contents: { role: "user" | "model"; parts: Record<string, unknown>[] }[] = [];
  const push = (role: "user" | "model", part: Record<string, unknown>): void => {
    const last = contents[contents.length - 1];
    if (last && last.role === role) last.parts.push(part);
    else contents.push({ role, parts: [part] });
  };
  // functionResponse.name 为官方必填：从配对 tool_call 反查（tool_call_id → function name）
  const toolNames = new Map<string, string>();
  for (const m of messages) {
    if (m.role === "assistant") for (const tc of m.tool_calls ?? []) toolNames.set(tc.id, tc.function.name);
  }
  for (const m of messages) {
    if (m.role === "system") {
      if (m.content) systemParts.push(m.content);
      continue;
    }
    if (m.role === "tool") {
      let parsed: unknown = {};
      try {
        parsed = m.content && m.content.trim() !== "" ? (JSON.parse(m.content) as unknown) : {};
      } catch {
        parsed = { output: m.content ?? "" }; // 非对象结果包成 {output}（官方 response 需为对象）
      }
      push("user", {
        functionResponse: {
          name: toolNames.get(m.tool_call_id ?? "") ?? "",
          response: parsed !== null && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : { output: String(parsed) },
        },
      });
      continue;
    }
    const role = m.role === "assistant" ? "model" : "user";
    if (m.role === "assistant" && m.tool_calls) {
      if (m.content) push("model", { text: m.content });
      for (const tc of m.tool_calls) {
        let args: Record<string, unknown> = {};
        try {
          const raw = tc.function.arguments.trim() === "" ? {} : (JSON.parse(tc.function.arguments) as unknown);
          if (raw !== null && typeof raw === "object" && !Array.isArray(raw)) args = raw as Record<string, unknown>;
        } catch {
          args = {};
        }
        push("model", { functionCall: { name: tc.function.name, args } });
      }
      continue;
    }
    // user 侧带图：先 text 再 inlineData（官方 parts 数组混排）。assistant 侧不产图片。
    const imageParts = m.role === "user" ? geminiImageParts(m) : [];
    if (m.content !== null && m.content !== "") push(role, { text: m.content });
    for (const part of imageParts) push(role, part);
    if ((m.content === null || m.content === "") && imageParts.length === 0) push(role, { text: "" });
  }
  const body: Record<string, unknown> = { contents };

/** user 消息的图片 parts：data URL 拆成 Gemini 官方的 inlineData（mimeType + base64 data）。
 *  非 data URL 不猜：宁可用一个 text part 说明「这张图没带上」，也不发一个空 inlineData
 *  （上游对空 data 的 400 与「图没到」是两件事，后者至少能从对话里看出来）。 */
function geminiImageParts(m: ProviderMessage): Record<string, unknown>[] {
  const parts = (m as ProviderMessageWithImage).contentParts;
  if (parts === undefined || parts.length === 0) return [];
  const out: Record<string, unknown>[] = [];
  for (const p of parts as readonly ProviderContentImage[]) {
    if (p.type !== "image") continue;
    const mm = /^data:(image\/[a-zA-Z0-9.+-]+);base64,(.*)$/s.exec(p.dataUrl);
    if (mm === null) {
      out.push({ text: "[image: 非 data URL 的图片引用已忽略——只接受 data:image/...;base64,...]" });
      continue;
    }
    out.push({ inlineData: { mimeType: mm[1], data: mm[2] } });
  }
  return out;
}
  // 思考档位（§S8）：Gemini 收的是 token 预算，放在 generationConfig.thinkingConfig 里。
  if (opts.thinkingBudget !== undefined && opts.thinkingBudget > 0) {
    body.generationConfig = { thinkingConfig: { thinkingBudget: opts.thinkingBudget } };
  }
  if (systemParts.length > 0) body.systemInstruction = { parts: [{ text: systemParts.join("\n\n") }] };
  if (tools && tools.length > 0) {
    body.tools = [
      {
        functionDeclarations: tools.map((t) => ({
          name: t.name,
          ...(t.description ? { description: t.description } : {}),
          parameters: t.parameters,
        })),
      },
    ];
  }
  return body;
}

/** 流式一轮对话：SSE chunk → 统一事件流。 */
export async function* streamGemini(
  messages: ProviderMessage[],
  opts: GeminiOptions = {},
  tools?: ProviderToolSpec[],
  call?: { signal?: AbortSignal },
): AsyncGenerator<ModelOutput> {
  const label = opts.label ?? "Gemini";
  const envName = opts.apiKeyEnv ?? "GEMINI_API_KEY";
  const apiKey = opts.apiKey ?? process.env[envName];
  if (!apiKey) throw new Error(`${envName} 未设置（key 只从环境变量读取，不落文件）`);
  const model = opts.model ?? process.env.GEMINI_MODEL ?? "gemini-2.5-flash";
  const baseURL = opts.baseURL ?? "https://generativelanguage.googleapis.com";
  const doFetch = opts.fetchImpl ?? fetch;
  const toolRequestScope = randomUUID(); // 不同请求的缺省调用 id 不能共用从零开始的序号。

  // 根因 4：停滞守卫改由 establishStream 逐次新建（静默窗口，不是总时长），成功建连后交回
  // 本函数继续管流体。建连期失败（429/5xx/网络抖动）按指数退避 + full jitter 重试；
  // 不变量：res.ok 之后绝不重放（流已产出），调用方取消与停滞都不重试。
  let guard: StallGuard | undefined;
  const est = await establishStream({
    label,
    url: `${baseURL}/v1beta/models/${encodeURIComponent(model)}:streamGenerateContent?alt=sse`,
    init: {
      method: "POST",
      headers: { "Content-Type": "application/json", "x-goog-api-key": apiKey },
      body: JSON.stringify(toGeminiBody(messages, tools, { ...(opts.thinkingBudget !== undefined ? { thinkingBudget: opts.thinkingBudget } : {}) })),
    },
    fetchImpl: doFetch,
    stallMs: opts.stallTimeoutMs ?? DEFAULT_STALL_MS,
    ...(call?.signal !== undefined ? { callerSignal: call.signal } : {}),
  });
  const res = est.res;
  guard = est.guard;
  if (!res.body) {
    guard?.dispose();
    throw new Error(`${label} 流式响应缺少 body`);
  }

  const decoder = new TextDecoder();
  const reader = res.body.getReader();
  let buf = "";
  let callId = "gemini-a";
  let inputTokens: number | null = null;
  let outputTokens: number | null = null;
  /** 缓存命中分块：**缺报时不落 0**（与 anthropic/openai 两侧同一条规矩：缺报 ≠ 命中为零）。 */
  let cacheRead: number | null = null;
  let callSeq = 0;
  // finishReason 随候选块到达（中间 chunk 常是 null）：记最后一个非空的。
  let finishReason: string | null | undefined;
  // prompt 级拦截的第二份量纲：这一支到用时 candidates 缺席，光看 finishReason 一条道会全盲。
  let blockReason: string | undefined;

  try {
    let done = false;
    while (!done) {
      const read = await reader.read();
      if (read.done) break;
      guard?.bump(); // 有分片 → 续期（只有完全静默才会到点）
      buf += decoder.decode(read.value, { stream: true });
      let nl: number;
      while ((nl = buf.indexOf("\n")) >= 0) {
        const line = buf.slice(0, nl).trim();
        buf = buf.slice(nl + 1);
        if (!line.startsWith("data:")) continue;
        const payload = line.slice(5).trim();
        if (!payload) continue;
        // C7（审查 P2）容错边界修正（审查 S1-6）：只对「不是帧的行」容错——注释心跳、
        // 网关塞进来的非 JSON 文本。以 { 开头的真帧 parse 失败不得静默 continue：那意味着
        // 上游把一帧截断了，跳过 = 少一截正文/少一个 tool_call 分片，而流随后正常收尾会让
        // 本轮以「不完整输出」成功收束（loop 无从得知）。同文件 parseArgs 的口径就是协议级
        // 异常 fail loud，这里与之对齐。
        let chunk: GeminiChunk;
        try {
          chunk = JSON.parse(payload) as GeminiChunk;
        } catch {
          if (!payload.startsWith("{")) continue; // 心跳/注释/网关杂帧：容忍
          throw new Error(`${label} SSE 帧损坏（半帧截断？）：JSON 解析失败，拒绝静默丢字`);
        }
        if (chunk.error) {
          const e = chunk.error;
          throw new Error(`${label} 流错误 ${e.status ?? String(e.code ?? "unknown")}: ${e.message ?? ""}`);
        }
        if (chunk.usageMetadata) {
          // chunk 间为累计值：直接覆盖，绝不累加
          const u = chunk.usageMetadata;
          inputTokens = u.promptTokenCount ?? inputTokens;
          outputTokens = (u.candidatesTokenCount ?? 0) + (u.thoughtsTokenCount ?? 0) || outputTokens;
          cacheRead = u.cachedContentTokenCount ?? cacheRead;
        }
        const cand = chunk.candidates?.[0];
        if (cand?.finishReason) finishReason = cand.finishReason;
        // 两个字段互斥出现（被拦的那一帧没有 candidates），所以各读各的、末尾合并。
        if (chunk.promptFeedback?.blockReason) blockReason = chunk.promptFeedback.blockReason;
        const parts = cand?.content?.parts ?? [];
        for (const part of parts) {
          // thought=true 的 part 是思考内容（thinkingBudget 开启时才有）→ 独立事件。
          if (part.thought === true && part.text) {
            yield { type: "thinking_delta", callId, text: part.text };
          }
          if (part.text && part.thought !== true) {
            yield { type: "assistant_delta", callId, text: part.text };
          } else if (part.functionCall) {
            const fc = part.functionCall;
            yield {
              type: "tool_call",
              id: fc.id ?? `gemini-call-${toolRequestScope}-${String(callSeq++)}`,
              name: fc.name ?? "",
              args: parseArgs(fc.args, label),
            };
          }
          // 其余 part 形态（未知扩展）优雅跳过
        }
      }
    }
    if (inputTokens !== null || outputTokens !== null || cacheRead !== null) {
      yield {
        type: "usage",
        // 口径与另两个适配器**同一个**：`inputTokens` 含缓存总量，分块是其中的一部分
        // （所以这里**不加**——`promptTokenCount` 本来就含，与 anthropic 那边「不含、要加」正相反）。
        inputTokens: inputTokens ?? 0,
        outputTokens: outputTokens ?? 0,
        ...(cacheRead !== null ? { cacheReadInputTokens: cacheRead } : {}),
      };
    }
    // 流正常收尾，但停止读数说这一轮没说完（MAX_TOKENS＝篇幅不够 / SAFETY 家族＝被拦）。
    // candidates[0].finishReason 与 promptFeedback.blockReason 互斥到值：谁在场用谁。
    // 上面 C7 那条守的是「半帧被截断」，这里守的是「帧到齐、篇幅没给够/被拦」。
    const truncated = turnTruncatedEvent(callId, finishReason ?? blockReason, outputTokens);
    if (truncated) yield truncated;
    // 同位置、互斥：candidates[0].finishReason 与 promptFeedback.blockReason 都没见到
    // ⇒ 「不知道它说没说」的证据（Gemini 正常收尾是有 finishReason 的，缺席同样可疑）。
    const stopMissing = turnStopMissingEvent(callId, finishReason ?? blockReason, outputTokens);
    if (stopMissing) yield stopMissing;
  } finally {
    guard?.dispose();
    // 消费者提前 break / 出错退出时主动取消 body，否则连接与对端资源一直挂着。
    void reader.cancel().catch(() => {});
  }
}
